CH, CAV, INF, SPU, ALL = 'Characters', 'Cavalry', 'Infantry', 'Special Units', 'Allies and Mercenaries'
def variants(key, title, comps):
    VAR[key] = {}; out = []
    for c, (lim, txt) in comps.items():
        VAR[key][c] = f'Byzantium: {title}' if len(comps) == 1 else f'Byzantium: {title} - {c}'
        out.append((VAR[key][c], lim, txt))
    return out
def L(**kw):
    out = {}
    for k, v in kw.items():
        cat = k.replace('_', ' ')
        if isinstance(v, tuple):
            lo, hi = v
            d = {}
            if lo: d['min'] = lo
            if hi and hi < 100: d['max'] = hi
            out[cat] = d
        else: out[cat] = {'max': v}
    return out
def dm(pts, extra=''):
    return [(f'Dismounted (-{pts} pts, Move 4)', -pts)]
HORSE_STD = ['Hand Weapon']

# ================================================================== EARLY BYZANTINES (book pp.34-43)
EB = []
def EBCH(name, stats, pts, rules=(), mx=None, warhorse=False, note='', page='38'):
    o = [('Light armour', 3), ('Heavy armour (replaces light armour)', 4), ('Bow', 3), ('Javelins', 2), ('Thrusting spear & shield', 4), ('Throwing spear & shield', 4), ('Kontos & buckler', 4),
         ('Kontarion & shield (replaces kontos & buckler)', 5), ('Barding', 4), ('Half-barding', 2)]
