    return U(CAV, name, [M(mname, st, pts, mn=5, weapons=['Hand Weapon', 'Light Armour', 'Bow', 'Buckler'], rules=['Superior Byzantine Cavalry'] + rules, options=o)], JC_TXT + note, mx=mx, page='38')
