# ================================================================== BULGARS & SLAVS (book pp.72-75)
BS = []
ES, LS, EBg, LB = 'Early Balkan Slavs', 'Later Balkan Slavs', 'Early Balkan Bulgars', 'Later Balkan Bulgars'
BULG, SLAV = [EBg, LB], [ES, LS]
STD = 'Army Standard Bearer (+15 pts; one Bagatur, Tarkan or Voevodo)'
def bchar(name, stats, pts, rules, mx, opts, txt, page='75'):
    return U(CH, name, [M(name, stats, pts, weapons=['Hand Weapon', 'Light Armour'], rules=list(rules), options=opts)], txt, mx=mx, page=page)
BOPT = [('Buckler', 1), ('Javelins', 2), ('Bow', 3), ('Thrusting spear', 2), ('Throwing spear', 2), ('Horse (Move 8)', 8), ('Half-barding', 2)]
SOPT = [('Buckler', 1), ('Shield', 2), ('Javelins', 2), ('Bow', 3), ('Thrusting spear', 2), ('Throwing spear', 2), ('Horse (Move 8)', 8), ('Large shield (Later Bulgar; on foot)', 2)]
BS.append(bchar('Khan', '8 6 6 4 4 3 6 3 8', 160, ['Army General', 'Expert Horsemen', 'Feigned Flight'], 1,
    [('Buckler', 1), ('Javelins', 2), ('Bow', 3), ('Thrusting spear', 2), ('Throwing spear', 2), ('Half-barding', 2), ('Heavy armour (replaces light armour)', 2), ('Large shield (Later Bulgar; on foot)', 2)],
    'Hand weapon and light armour. May have buckler (+1 pt), either javelins (+2 pts) or bow (+3 pts), and thrusting or throwing spear (+2 pts). Rides a horse. May have half-barding (+2 pts) and heavy armour (+2 pts). The Khan is the Army General (0-1). Later Balkan Bulgar characters on foot may have a large shield (+2 pts). All mounted Bulgar commanders are Expert Horsemen and may use Feigned Flight. The Bulgar Khans, and later the Tzars, were the supreme heads of the Bulgar state.'))
BS.append(bchar('Tarkan', '5 6 5 4 3 3 5 2 8', 80, ['Expert Horsemen (if mounted)', 'Feigned Flight (if mounted)'], None,
    copy.deepcopy(BOPT) + [('Kavkan (Army General; +25 pts; if no other Army General; Early Bulgars)', 25), ('Large shield (Later Bulgar; on foot)', 2), (STD, 15)],
    'Hand weapon and light armour. May have buckler (+1 pt), either javelins (+2 pts) or bow (+3 pts), and thrusting or throwing spear (+2 pts). May ride a horse (+8 pts), and may have half-barding (+2 pts). Army Standard Bearer Option: one Bagatur or Tarkan may be upgraded to Army Standard Bearer (+15 pts). Early Balkan Bulgar armies: if no other Army General is chosen, a Tarkan may be upgraded to Kavkan (+25 pts), who counts as Army General. All mounted Bulgar commanders are Expert Horsemen and may use Feigned Flight. Later Balkan Bulgar characters on foot may have a large shield (+2 pts).'))
BS.append(bchar('Bagatur', '5 4 4 4 3 2 4 2 8', 55, ['Expert Horsemen (if mounted)', 'Feigned Flight (if mounted)'], None,
    copy.deepcopy(BOPT) + [('Large shield (Later Bulgar; on foot)', 2), (STD, 15)],
    'Hand weapon and light armour. May have buckler (+1 pt), either javelins (+2 pts) or bow (+3 pts), and thrusting or throwing spear (+2 pts). May ride a horse (+8 pts), and may have half-barding (+2 pts). One Bagatur or Tarkan may be upgraded to Army Standard Bearer (+15 pts). Renowned Bagatur warriors inspired and led the troops into battle. All mounted Bulgar commanders are Expert Horsemen and may use Feigned Flight. Later Balkan Bulgar characters on foot may have a large shield (+2 pts).'))
BS.append(bchar('Voevodo', '5 4 4 4 3 2 5 2 8', 60, ['Feigned Flight (if mounted)'], None,
    [o for o in SOPT if 'Large' not in o[0]] + [('Grand Zhapan (Army General; +25 pts; Early Slavs; the only Voevodo)', 25), ('Knyaz (Army General; +25 pts; Later Slavs; one Voevodo)', 25), (STD, 15)],
    'Hand weapon and light armour. May have buckler (+1 pt), shield (+2 pts), either javelins (+2 pts) or bow (+3 pts), and either thrusting or throwing spear (+2 pts). May ride a horse (+8 pts). One Voevodo may be upgraded to Slav Army Standard Bearer (+15 pts). Mounted Slav characters have Feigned Flight. Early Balkan Slav armies: only one Voevodo may be chosen from the Commander entries, and he must be upgraded to Grand Zhapan (+25 pts) who counts as the Army General. Later Balkan Slav armies: one Voevodo may be upgraded to Knyaz (Prince) who counts as Army General (+25 pts).'))
BS.append(bchar('Zhupan', '5 4 4 4 3 1 4 2 7', 40, ['Feigned Flight (if mounted)'], None,
    [o for o in SOPT if 'Large' not in o[0]],
    'Hand weapon and light armour. May have buckler (+1 pt), shield (+2 pts), either javelins (+2 pts) or bow (+3 pts), and either thrusting or throwing spear (+2 pts). May ride a horse (+8 pts). Mounted Slav characters have Feigned Flight. In Early Balkan Slav armies only one Voevodo may be chosen from the Commander entries (Zhupans are not restricted).'))
WOPT = [('Throwing spear (replaces javelins; every other unit)', 1), ('Bow (replaces javelins; every other unit)', 2), ('Halberd (Slav; two units)', 2), ('Double-handed weapon (Slav; two units)', 3),
        ('Skirmishers (Feigned Flight)', 1), ('Later Warriors (Ld 5; not Light Infantry)', 1), ('Light armour (Later Bulgar Warriors with throwing spears)', 1), ('Large shield (Later Bulgar Warriors with throwing spears)', 1)]
BS.append(U(INF, 'Slav Brigands', [M('Slav Brigand', '5 2 2 3 3 1 2 1 4', 3, mn=5, weapons=['Hand Weapon', 'Javelin', 'Shield'], rules=['Light Troops', 'Warband', 'Stealth'], options=[('Skirmishers (Feigned Flight)', 1)])],
    'Mixed weapons (count as hand weapon and javelins) and shield. Any unit may be designated as Skirmishers (+1 pt); Slav Skirmishers have Feigned Flight. Light Infantry. Warband. Slav Warriors and Brigands have Stealth. Being mostly accomplished looters and brigands, early Bulgars and Slavs were extremely vulnerable when they encountered regular Byzantine troops. Not available to Later Balkan Slavs.', page='75'))
BS.append(U(INF, 'Warriors (Slav & Bulgar)', [M('Warrior', '5 3 3 3 3 1 3 1 4', 4, mn=5, weapons=['Hand Weapon', 'Javelin', 'Shield'], rules=['Light Troops', 'Warband', 'Stealth'], options=WOPT)],
    'Mixed weapons (count as hand weapon and javelins) and shield. Every other unit of Warriors may have throwing spear (+1 pt) or bow (+2 pts) instead of javelins. Two units of Slav Warriors may have either halberds (+2 pts), or double-handed weapons (+3 pts). Skirmisher Option: any Slav Warrior unit may be designated as Skirmishers (+1 pt); they have Feigned Flight. Light Infantry. Warband. Slav Warriors and Brigands have Stealth. Later Balkan Bulgars: Warriors are not subject to Warband Psychology Rule 2 and Rule 3. Any unit of Bulgar Foot Warriors may be upgraded to Later Warriors (+1 pt, Leadership 5); Later Warriors do not count as Light Infantry. Later Bulgar warriors with throwing spears may have light armour (+1 pt) and/or large shield (+1 pt). Warriors and Later Warriors may deploy behind a Palisade Fence (see the Balkan Ruse special rule).', page='75'))
BS.append(U(CAV, 'Bulgar Nobles', [M('Bulgar Noble', '8 4 4 3 3 1 4 1 8', 28, mn=5, weapons=['Hand Weapon', 'Bow', 'Light Armour'], rules=['Light Troops', 'Expert Horsemen', 'Feigned Flight'],
    options=[('Buckler', 1), ('Throwing spear', 1), ('Thrusting spear', 1), ('Half-barding', 2)])],
    'Hand weapon, bow and light armour. May have buckler (+1 pt), and either throwing or thrusting spear (+1 pt). May take half-barding (+2 pts). Light Cavalry. Bulgar cavalrymen with light armour are Expert Horsemen and may use Feigned Flight. If Nobles are taken, at least one unit of Horse Archers must be taken also (Early Balkan Bulgars: at least two units of Horse Archers or Elite Horse Archers). 0-2 units.', mx=2, page='75'))
BS.append(U(CAV, 'Bulgar Elite Horse Archers', [M('Elite Horse Archer', '8 3 4 3 3 1 4 1 7', 25, mn=5, weapons=['Hand Weapon', 'Bow'], rules=['Light Troops', 'Nomad Cavalry (Byzantium)'], options=[('Buckler', 1), ('Throwing spear', 1), ('Thrusting spear', 1), ('Light armour (Expert Horsemen, Feigned Flight)', 0)])],
    'Hand weapon and bow. May have buckler (+1 pt), and either throwing or thrusting spear (+1 pt). Light Cavalry. Bulgar cavalrymen with light armour are Expert Horsemen and may use Feigned Flight. All other Bulgar cavalry are Nomad Cavalry. Originally, the nomadic Bulgars fought from horseback. As they settled and mixed with the Slav peoples, Bulgar cavalry became rarer.', page='75'))
BS.append(U(CAV, 'Bulgar Horse Archers', [M('Horse Archer', '8 3 3 3 3 1 3 1 7', 21, mn=5, weapons=['Hand Weapon', 'Bow'], rules=['Light Troops', 'Nomad Cavalry (Byzantium)'], options=[('Buckler', 1), ('Throwing spear', 1), ('Thrusting spear', 1), ('Light armour (Expert Horsemen, Feigned Flight)', 0)])],
    'Hand weapon and bow. May have buckler (+1 pt), and either throwing or thrusting spear (+1 pt). Light Cavalry. Bulgar cavalrymen with light armour are Expert Horsemen and may use Feigned Flight. All other Bulgar cavalry are Nomad Cavalry.', page='75'))
BS.append(U(CAV, 'Slav Nobles', [M('Slav Noble', '8 3 3 3 3 1 3 1 7', 17, mn=5, weapons=['Hand Weapon', 'Javelin', 'Buckler'], rules=['Skirmishers (Byzantium)', 'Feigned Flight'], options=[('Shield (replaces buckler)', 1), ('Throwing spear', 1), ('Light armour', 2)])],
    'Hand weapon, javelins and buckler. May have shield instead of buckler (+1 pt), and throwing spear (+1 pt). Nobles may have light armour (+2 pts). Skirmishers. Feigned Flight. If Nobles are taken, at least one unit of Slav Cavalry must be taken also. 0-3 units. Early Balkan Slav armies may choose one unit of Slav Nobles; Slav Nobles may not be chosen in Bulgar armies.', mx=3, page='75'))
BS.append(U(CAV, 'Slav Cavalry', [M('Slav Cavalryman', '8 3 3 3 3 1 3 1 6', 15, mn=5, weapons=['Hand Weapon', 'Javelin', 'Buckler'], rules=['Skirmishers (Byzantium)', 'Feigned Flight'], options=[('Shield (replaces buckler)', 1), ('Throwing spear', 1)])],
    'Hand weapon, javelins and buckler. May have shield instead of buckler (+1 pt), and throwing spear (+1 pt). Skirmishers. Feigned Flight. Only the wealthiest Slav warriors fought from horseback. While the elusive cavalrymen of the Slavic tribes were a taxing opponent, the mainstay of Slavic warbands fought on foot.', page='75'))
BSV = variants('BS', 'Bulgars & Slavs', {
 ES: (L(Characters=33, Infantry=(33, 100), Cavalry=33), 'EARLY BALKAN SLAVS. Characters up to 33%; Infantry at least 33%; Cavalry up to 33% (one unit of Slav Nobles may be chosen). Special rule: only one Voevodo may be chosen from the Commander entries, and he must be upgraded to Grand Zhapan (+25 pts) who counts as the Army General.'),
 LS: (L(Characters=33, Infantry=(25, 100), Cavalry=50), 'LATER BALKAN SLAVS. Characters up to 33%; Infantry at least 25% (Slav Brigands may not be chosen); Cavalry up to 50%. Special rule: one Voevodo may be upgraded to Knyaz (Prince) who counts as Army General (+25 pts).'),
 EBg: (L(Characters=33, Infantry=(25, 100)), 'EARLY BALKAN BULGARS. Characters up to 33%; Infantry at least 25%, up to 33% of the points may be spent on Slav infantry (not enforced); Cavalry any amount, up to 25% of the points may be spent on Slav cavalry (not enforced; Slav Nobles may not be chosen). Special rules: if Nobles are chosen, at least two units of Horse Archers or Elite Horse Archers must be taken as well. If no other Army General is chosen, a Tarkan may be upgraded to Kavkan (+25 pts), who counts as Army General.'),
 LB: (L(Characters=33, Infantry=(25, 100), Cavalry=33), 'LATER BALKAN BULGARS. Characters up to 33%; Infantry at least 25%, up to 33% of the points may be spent on Slav infantry (not enforced); Cavalry up to 33%, up to 25% of the points on Slav cavalry (not enforced; Slav Nobles may not be chosen). Special rules: Bulgar Foot Warriors are not subject to Warband Psychology Rule 2 and Rule 3. Any unit of Bulgar Foot Warriors may be upgraded to Later Warriors (+1 pt, Leadership 5). Warriors may deploy behind a Palisade Fence (up to 18" at 4 pts per inch, Balkan Ruse rule 2; documented only; requires at least 33% of the points spent on Warriors or Later Warriors).')})
BS_NOTES = ('BULGARS & SLAVS (Byzantium: Beyond the Golden Gate, pp.72-75): Early & Later Balkan Bulgar and Slav armies, 643-1018 AD. Special rules: Balkan Ruse - Bulgars and Slavs may always place D3 patches of difficult terrain (about 6" by 6") in their deployment zone before deployment begins. Bulgar and Slav infantry are Warband, Light Infantry with Stealth.')
LISTS.append(('BS', 'Bulgars & Slavs (Byzantium)', 'Bulgars_and_Slavs_Byzantium.cat', BS, BSV, BS_NOTES))
UNAV += [('BS', u, SLAV) for u in ('Khan', 'Tarkan', 'Bagatur', 'Bulgar Nobles', 'Bulgar Elite Horse Archers', 'Bulgar Horse Archers')]
UNAV += [('BS', u, BULG) for u in ('Voevodo', 'Zhupan')]
UNAV += [('BS', 'Slav Brigands', [LS]), ('BS', 'Slav Nobles', BULG)]
UNAV += [('BS', 'Slav Nobles', []) ] if False else []
OPTAV += [('BS', 'Tarkan', 'Kavkan (Army General; +25 pts; if no other Army General; Early Bulgars)', [EBg]),
          ('BS', 'Voevodo', 'Grand Zhapan (Army General; +25 pts; Early Slavs; the only Voevodo)', [ES]), ('BS', 'Voevodo', 'Knyaz (Army General; +25 pts; Later Slavs; one Voevodo)', [LS])]
for u in ('Khan', 'Tarkan', 'Bagatur'): OPTAV.append(('BS', u, 'Large shield (Later Bulgar; on foot)', [LB]))
for u in ('Tarkan', 'Bagatur'): OPTAV.append(('BS', u, STD, BULG))
