NOWH = [AC, UM]   # no warhorses / barding
CHO = [('Horse (Move 8)', 8), ('Warhorse (Move 8)', 16), ('Light armour', 3), ('Heavy armour (replaces light armour)', 4), ('Shield', 2), ('Short bow', 2), ('Bow', 3), ('Half-barding', 2), ('Barding', 4), ('Riding Horses (leading infantry; +2 pts)', 2), ('Riding Camels (leading infantry; +2 pts)', 2)]
def echar(name, stats, pts, rules, mx, extra, txt, spear=True, twoh=False):
    o = copy.deepcopy(CHO) + list(extra)
    if spear: o.append(('Thrusting spear', 2))
    if twoh: o.append(('Two-handed weapon (on foot)', 2))
    return U(CH, name, [M(name, stats, pts, weapons=['Hand Weapon'], rules=list(rules), options=o)], txt, mx=mx, page='82')
EQ = 'Hand weapon. May ride a horse (+8 pts), a warhorse (+16 pts), and have light armour (+3 pts) or heavy armour (+4 pts), shield (+2 pts), short bow (+2 pts) or bow (+3 pts). '
EQ2 = 'Mounted characters may have half-barding (+2 pts) or barding (+4 pts) for their mounts. Characters leading units of infantry or dismounted cavalry may be Riding Horses (+2 pts) or Riding Camels (+2 pts). In Arab Conquest and Umayyad armies characters may not ride warhorses and may not take half-barding or barding for their mounts. '
EC.append(echar('Khalifa', '4 5 5 4 3 3 6 2 10', 165, ['Army General'], 1, [], EQ + EQ2 + 'The Khalifa is the Army General (0-1), and may only be fielded in Umayyad, Abbasid and Fatimid armies exceeding a total value of 2,000 pts.', spear=False))
EC.append(echar('Amir', '4 5 5 4 3 3 5 2 9', 110, [], 2, [('Army General (+25 pts; if no Khalifa)', 25)], EQ + 'Amirs may have thrusting spear (+2 pts). ' + EQ2 + 'Amir as Army General: if no Khalifa is chosen, an Amir may be upgraded to Army General (+25 pts). 0-2. Not available to Arab Conquest armies (their only general is a Companion upgraded to Army General).'))
EC.append(echar('Companions', '5 4 4 4 3 2 5 3 9', 85, ['Companion (Byzantium)'], 3, [('Army General (+25 pts; Arab Conquest only)', 25), ('Two-handed weapon (on foot)', 2)], EQ + 'May have thrusting spear (+2 pts). May have a two-handed weapon, if on foot (+2 pts). ' + EQ2 + 'Special Rules: Companions - units led by a Companion may re-roll failed Panic tests. The Companion is not subject to Warband Psychology. 0-3. Arab Conquest armies only: the only general available is a Companion upgraded to Army General (+25 pts).', twoh=False))
EC.append(echar('Marzban', '4 4 5 3 3 2 5 2 8', 55, ['Marzban (Byzantium)'], None, [('Two-handed weapon (on foot)', 2)], EQ + 'May have thrusting spear (+2 pts). Marzbans may have half-barding (+2 pts) for their mounts. Special Rule: Marzban - must lead a Khurasan Cavalry unit.'))
EC.append(echar('Shaikh/Qa\'id', '5 4 4 4 3 2 4 2 8', 55, [], None, [('Two-handed weapon (on foot)', 2)], EQ + 'May have thrusting spear (+2 pts). May have a two-handed weapon, if on foot (+2 pts). ' + EQ2))
EC.append(U(CH, 'Army Standard Bearer', [M('Army Standard Bearer', '4 4 4 4 3 2 5 2 8', 75, weapons=['Hand Weapon'], rules=['Army Standard'], options=[('Horse (Move 8)', 8), ('Warhorse (Move 8)', 16), ('Light armour', 3), ('Heavy armour (replaces light armour)', 4), ('Shield', 2), ('Half-barding', 2), ('Barding', 4), ('Riding Horses (leading dismounted cavalry; +2 pts)', 2), ('Riding Camels (leading dismounted cavalry; +2 pts)', 2)])],
    'Hand weapon. May ride a horse (+8 pts), a warhorse (+16 pts), and have light armour (+3 pts), heavy armour (+4 pts) and shield (+2 pts). The Army Standard Bearer may have half-barding (+2 pts) or barding (+4 pts). Standard Bearers leading units of dismounted cavalry may be Riding Horses (+2 pts) or Riding Camels (+2 pts). 0-1.', mx=1, page='82'))
